/**
 * Open a seal with each password in order: every password with the configured
 * iterations first, then every password with the legacy count. Only an HMAC
 * failure (wrong password) moves on to the next attempt; any other error is
 * rethrown as is.
 */
async function unsealWithPasswords(
  sealed: string,
  passwords: string[],
  config: SessionConfig,
  sealOptions: SealOptions,
): Promise<Partial<Session>> {
  const mark = (unsealed: Partial<Session>, reseal: boolean) => {
    if (unsealed && reseal) {
      (unsealed as any)[kLegacySeal] = true;
    }
    return unsealed;
  };
  let firstError: unknown;
  for (const [index, password] of passwords.entries()) {
    try {
      return mark((await unseal(sealed, password, sealOptions)) as Partial<Session>, index > 0);
    } catch (error) {
      if (!isBadHmac(error)) {
        throw error;
      }
      firstError ??= error;
    }
  }
  // TODO: Remove this fallback (and `legacySealFallback`) in v3. Removing it
  // in a v2 release would invalidate existing sessions sealed with 1 iteration.
  // Sessions sealed before the default PBKDF2 iterations were raised from 1
  // to 8192 fail HMAC verification; retry with the legacy count so existing
