describe("password rotation", () => {
  const NEW = "n".repeat(40);
  const OLD = "o".repeat(40);
  const OTHER = "x".repeat(40);
  const legacyOptions = {
    ...sealDefaults,
    encryption: { ...sealDefaults.encryption, iterations: 1 },
    integrity: { ...sealDefaults.integrity, iterations: 1 },
  };

  let ctr = 0;
  const nextName = () => `h3-rot-${++ctr}`;
  const payload = () => ({ id: "orig", createdAt: Date.now() - 1000, data: { foo: "bar" } });
  const cookieValue = (res: Response, name: string) => {
    const found = res.headers.getSetCookie().filter((c) => c.startsWith(`${name}=`));
    return found.map((c) => decodeURIComponent(c.match(/=([^;]*)/)![1]));
  };
  const route = (config: SessionConfig) => {
    const path = `/${config.name}`;
    t.app.get(path, async (event) => {
      const session = await getSession(event, config);
      return { id: session.id, createdAt: session.createdAt, data: session.data };
    });
    return path;
  };
  const fake = { toFake: ["Date"] as "Date"[] };

  it("seals with the first password only", async () => {
    const config: SessionConfig = { name: nextName(), password: [NEW, OLD] };
    t.app.get(`/${config.name}`, async (event) => {
      await useSession(event, config);
      return "ok";
    });
    const res = await t.fetch(`/${config.name}`);
    const [sealed] = cookieValue(res, config.name!);
    expect(await unseal(sealed, NEW, sealDefaults)).toMatchObject({ createdAt: expect.any(Number) });
    await expect(unseal(sealed, OLD, sealDefaults)).rejects.toThrow("Bad hmac value");
  });

  it("opens sessions sealed with an older password and reseals them with the first", async () => {
    const config: SessionConfig = { name: nextName(), password: [NEW, OLD] };
    const original = payload();
    const sealed = await seal(original, OLD, sealDefaults);
    const res = await t.fetch(route(config), { headers: { Cookie: `${config.name}=${sealed}` } });
    expect(await res.json()).toMatchObject(original);

    const resealed = cookieValue(res, config.name!);
    expect(resealed).toHaveLength(1);
    expect(await unseal(resealed[0], NEW, sealDefaults)).toMatchObject(original);
    await expect(unseal(resealed[0], OLD, sealDefaults)).rejects.toThrow("Bad hmac value");
  });

  it("does not reseal sessions sealed with the first password", async () => {
    const config: SessionConfig = { name: nextName(), password: [NEW, OLD] };
    const original = payload();
    const sealed = await seal(original, NEW, sealDefaults);
    const res = await t.fetch(route(config), { headers: { Cookie: `${config.name}=${sealed}` } });
    expect(await res.json()).toMatchObject(original);
    expect(res.headers.getSetCookie()).toHaveLength(0);
  });

  it("opens header sessions sealed with an older password without resealing", async () => {
    const config: SessionConfig = { name: nextName(), password: [NEW, OLD] };
    const original = payload();
    const sealed = await seal(original, OLD, sealDefaults);
    const res = await t.fetch(route(config), {
      headers: { [`x-${config.name}-session`]: sealed },
    });
    expect(await res.json()).toMatchObject(original);
    expect(res.headers.getSetCookie()).toHaveLength(0);
  });

  it("rejects sessions sealed with an unknown password", async () => {
    const config: SessionConfig = { name: nextName(), password: [NEW, OLD] };
    const sealed = await seal(payload(), OTHER, sealDefaults);
    const res = await t.fetch(route(config), { headers: { Cookie: `${config.name}=${sealed}` } });
    const body = await res.json();
    expect(body.id).not.toBe("orig");
    expect(body.data).toEqual({});
  });

  it("behaves the same with a string and a one-item list", async () => {
    const original = payload();
    const sealed = await seal(original, NEW, sealDefaults);
    const legacy = await seal(original, NEW, legacyOptions);
    const custom = { ...sealDefaults, ttl: 0 };
    const results: unknown[] = [];
    for (const pw of [NEW, [NEW]]) {
      for (const extra of [{}, { maxAge: 60 }, { idleTimeout: 60 }, { seal: custom }]) {
        const config: SessionConfig = { name: nextName(), password: pw, ...extra };
        const res = await t.fetch(route(config), { headers: { Cookie: `${config.name}=${sealed}` } });
        results.push([await res.json(), res.headers.getSetCookie().length]);
      }
      const config: SessionConfig = { name: nextName(), password: pw, legacySealFallback: false };
      const res = await t.fetch(route(config), { headers: { Cookie: `${config.name}=${legacy}` } });
      expect((await res.json()).id).not.toBe("orig");
      const config2: SessionConfig = { name: nextName(), password: pw };
      const res2 = await t.fetch(route(config2), { headers: { Cookie: `${config2.name}=${legacy}` } });
      expect((await res2.json()).id).toBe("orig");
    }
    const half = results.length / 2;
    expect(results.slice(0, half)).toEqual(results.slice(half));
  });

  it("restores legacy seals sealed with an older or the first password", async () => {
    for (const pw of [OLD, NEW]) {
      const config: SessionConfig = { name: nextName(), password: [NEW, OLD] };
      const original = payload();
      const sealed = await seal(original, pw, legacyOptions);
      const res = await t.fetch(route(config), { headers: { Cookie: `${config.name}=${sealed}` } });
      expect(await res.json()).toMatchObject(original);
      const resealed = cookieValue(res, config.name!);
      expect(resealed).toHaveLength(1);
      expect(await unseal(resealed[0], NEW, sealDefaults)).toMatchObject(original);

      const strict: SessionConfig = { ...config, name: nextName(), legacySealFallback: false };
      const res2 = await t.fetch(route(strict), { headers: { Cookie: `${strict.name}=${sealed}` } });
      expect((await res2.json()).id).not.toBe("orig");
    }
  });

  it("rejects an empty list or empty items", async () => {
    for (const pw of [[], ["", NEW], [NEW, ""]]) {
      const config: SessionConfig = { name: nextName(), password: pw };
      const sealed = await seal(payload(), NEW, sealDefaults);
      await expect(unsealSession(undefined as any, config, sealed)).rejects.toThrow(
        "Empty password",
      );
      t.app.get(`/${config.name}`, async (event) => {
        await sealSession(event, config);
        return "ok";
      });
      const res = await t.fetch(`/${config.name}`);
      expect(res.status).toBe(500);
      expect(res.headers.getSetCookie()).toHaveLength(0);
      t.app.get(`/${config.name}-use`, async (event) => {
        await useSession(event, config);
        return "ok";
      });
      const res2 = await t.fetch(`/${config.name}-use`);
      expect(res2.headers.getSetCookie()).toHaveLength(0);
    }
    t.errors.length = 0;
  });

  it("expires sessions opened with an older password", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ ...fake, now: t0 });
    try {
      for (const extra of [{ maxAge: 60 }, { idleTimeout: 60 }]) {
        const config: SessionConfig = { name: nextName(), password: [NEW, OLD], ...extra };
        const sealed = await seal(
          { id: "orig", createdAt: t0, lastSeenAt: t0, data: {} },
          OLD,
          { ...sealDefaults, ttl: 0 },
        );
        vi.setSystemTime(t0 + 61_000);
        await expect(unsealSession(undefined as any, config, sealed)).rejects.toThrow(
          "Session expired!",
        );
        const res = await t.fetch(route(config), {
          headers: { Cookie: `${config.name}=${sealed}` },
        });
        expect((await res.json()).id).not.toBe("orig");
        vi.setSystemTime(t0);
      }
    } finally {
      vi.useRealTimers();
    }
  });

  it("does not try other passwords after a non-HMAC error", async () => {
    const config: SessionConfig = { name: nextName(), password: [NEW, OLD] };
    await expect(unsealSession(undefined as any, config, "garbage")).rejects.toThrow(
      "Incorrect number of sealed components",
    );

    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ ...fake, now: t0 });
    const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
    try {
      const expired = await seal(payload(), OLD, { ...sealDefaults, ttl: 1000 });
      vi.setSystemTime(t0 + 60_000);
      deriveBits.mockClear();
      await expect(unsealSession(undefined as any, config, expired)).rejects.toThrow(
        "Expired seal",
      );
      // The seal is rejected before any key derivation
      expect(deriveBits).not.toHaveBeenCalled();
    } finally {
      deriveBits.mockRestore();
      vi.useRealTimers();
    }
  });

  it("tries passwords in order", async () => {
    const [A, B] = ["a".repeat(40), "b".repeat(40)];
    const original = payload();
    const sealed = await seal(original, B, sealDefaults);
    const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
    try {
      deriveBits.mockClear();
      const config: SessionConfig = { name: nextName(), password: [A, B] };
      expect(await unsealSession(undefined as any, config, sealed)).toMatchObject(original);
      // A: integrity only (HMAC fails); B: integrity + encryption
      expect(deriveBits).toHaveBeenCalledTimes(3);
    } finally {
      deriveBits.mockRestore();
    }
  });

  it("limits an invalid session to 2N attempts", async () => {
    const passwords = ["a".repeat(40), "b".repeat(40), "c".repeat(40)];
    const sealed = await seal(payload(), OTHER, sealDefaults);
    const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
    try {
      deriveBits.mockClear();
      const config: SessionConfig = { name: nextName(), password: passwords };
      await expect(unsealSession(undefined as any, config, sealed)).rejects.toThrow(
        "Bad hmac value",
      );
      // One HMAC derivation per attempt: N current + N legacy
      expect(deriveBits).toHaveBeenCalledTimes(passwords.length * 2);
    } finally {
      deriveBits.mockRestore();
    }
  });
});

