        const strict: SessionConfig = { ...config, name: nextName(), legacySealFallback: false };
        const res2 = await t.fetch(route(strict), { headers: { Cookie: `${strict.name}=${sealed}` } });
        expect((await res2.json()).id).not.toBe("orig");
